import json
def M(n,t): return {"label":"Australian Department of Agriculture (Micor) — %s, dogs%s"%(n,t),"url":"https://micor.agriculture.gov.au/live-animals/%s/dogs"%n.lower()}
S={
"eg":{"country":"Egypt","src":M("Egypt"," (based on Egyptian Ministry of Agriculture correspondence, 18 December 2025)"),"head":"Microchip first, then a rabies vaccine at least 21 days before travel, plus a government vet certificate.",
"lines":["The Australian agriculture department says it received these rules from the Egyptian Ministry of Agriculture in December 2025: an ISO microchip whose number is on every document, and a valid rabies vaccination certificate.","The rabies vaccine must be given after the microchip, at least 21 days before travel, and still be valid on entry.","An official veterinary health certificate from a government-authorised vet in the country of origin is also required, with original documents. This is Australian guidance, so confirm with the Egyptian ministry."]},
"vn":{"country":"Vietnam","src":M("Vietnam"," (contact for MARD Veterinary Department)"),"head":"Vaccinate against rabies at least 30 days before departure; ask the Veterinary Department about the permit.",
"lines":["The Australian agriculture department says the pet must be vaccinated against rabies at least 30 days before departure, and the certificate must name the practice, the attending vet, the owner and the animal, with microchip number, vaccine, batch and use-by date.","It points exporters to the Veterinary Department of Vietnam's Ministry of Agriculture and Rural Development in Hanoi (spsvietnam@mard.gov.vn) for the import process and any permit.","The page does not publish Vietnam's own rules in full, so the ministry is the place to confirm."]},
"lb":{"country":"Lebanon","src":M("Lebanon"," (contact for the Directorate of Animal Resources)"),"head":"No published rule set: Lebanon's Directorate of Animal Resources decides the import process.",
"lines":["The Australian agriculture department does not list Lebanon's pet requirements; it says health requirements are those set by Lebanon and directs exporters to the Directorate of Animal Resources at info@agriculture.gov.lb.","Any import permit the directorate issues sets the conditions your pet must meet, so ask for it before booking the flight.","The Australian entry was last reviewed in July 2021, so treat it as a contact route, not a rulebook."]},
"kh":{"country":"Cambodia","src":M("Cambodia"," (contact for the Ministry of Agriculture, Forestry and Fisheries)"),"head":"No published rule set: ask the Ministry of Agriculture, Forestry and Fisheries.",
"lines":["The Australian agriculture department says Cambodia's health requirements are those set by the importing country and directs exporters to the Ministry of Agriculture, Forestry and Fisheries at info@maff.gov.kh.","If the ministry issues an import permit, the animal must meet everything written in it.","The Australian entry was last reviewed in June 2021, so it only points to the right office; confirm the rules and any quarantine step with the ministry before travel."]}}
for k,v in S.items(): json.dump(v,open('dup_work/petspecs/%s.json'%k,'w',encoding='utf8'),ensure_ascii=False,separators=(',',':'))
